const valueOrNull = (value) => {
  if (value === undefined || value === null) return null;
  if (typeof value === 'string' && value.trim() === '') return null;
  return value;
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value === 1;
  if (typeof value === 'string') {
    return ['true', '1', 'yes', 'on'].includes(value.trim().toLowerCase());
  }
  return false;
};

const generateUuid = () => {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
    const random = Math.floor(Math.random() * 16);
    const value = character === 'x' ? random : (random & 0x3) | 0x8;
    return value.toString(16);
  });
};

const payload = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const timestamp = new Date().toISOString();

return [{
  json: {
    lead_id: generateUuid(),
    source: {
      type: 'whatsapp',
      external_id: valueOrNull(payload.message_id),
      received_at: timestamp
    },
    contact: {
      name: valueOrNull(payload.profile_name),
      phone_raw: valueOrNull(payload.wa_id),
      phone_normalized: null,
      email_raw: valueOrNull(payload.email_address),
      email_normalized: null,
      consent: toBoolean(payload.opt_in)
    },
    business: {
      company_name: null,
      service_interest: valueOrNull(payload.service_interest),
      country: valueOrNull(payload.country_code),
      industry: null,
      company_size: null,
      strategic_account: false
    },
    request: {
      message: valueOrNull(payload.text),
      urgency: 'unknown'
    },
    processing: {
      status: 'processing',
      retry_count: 0,
      last_error: null,
      updated_at: timestamp,
      current_workflow: 'WF01_whatsapp_intake',
      next_workflow: 'WF02_validation_identity'
    },
    metadata: {
      schema_version: '1.0',
      workflow_version: '1.0'
    }
  }
}];
